  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["scale","seed","inkColor","accentColor","secondaryColor","tertiaryColor","loop","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  scale: 1,
  seed: 1,
  inkColor: "#1c1a17",
  accentColor: "#e4572e",
  secondaryColor: "#cbbc9f",
  tertiaryColor: "#7e776b",
  loop: false,
  speed: 1,
};

type BauhausBuildElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof BauhausBuildBase>;

const BauhausBuildInner = forwardRef<
  HTMLDivElement,
  BauhausBuildElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<BauhausBuild>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <BauhausBuildBase
          {...(componentProps as unknown as ComponentProps<typeof BauhausBuildBase>)}
        />
      </div>
    </Sequence>
  );
});

export const BauhausBuild = Interactive.withSchema({
  Component: BauhausBuildInner,
  componentName: "<BauhausBuild>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
